('chorionicity_help_dichorionic','ka','თითოეულ პატარას საკუთარი პლაცენტა აქვს — ეს ყველაზე დაბალი რისკის მქონე ტიპია და ტყუპების უმეტესობა ამ ჯგუფს მიეკუთვნება.','app'),
('chorionicity_help_mcda','ka','პატარებს საერთო პლაცენტა აქვთ (ჩვეულებრივ, იდენტურ ტყუპებში) — TTTS-ის (ტყუპიდან ტყუპზე ტრანსფუზიის სინდრომი) რისკის გამო ექოსკოპია უფრო ხშირად ინიშნება.','app'),
('chorionicity_help_mcma','ka','პატარებს საერთო პლაცენტა და სანაყოფე პარკი აქვთ — ეს იშვიათი შემთხვევაა და განსაკუთრებით ხშირ მონიტორინგს საჭიროებს (არსებობს ჭიპლარის გადახლართვის რისკიც).','app'),
('chorionicity_help_unknown','ka','ჩვეულებრივ, 10-14-ე კვირის ექოსკოპიაზე (ვადის დასადგენი კვლევა) დგინდება — ექიმი შეგატყობინებთ. საერთო პლაცენტის შემთხვევაში ექოსკოპია უფრო ხშირად იგეგმება.','app'),
