('preemie_backfill_term','ka','დიახ, ვადაზე (37+ კვირა)','app'),
('preemie_backfill_weeks','ka','კვირაზე დაიბადა','app'),
('preemie_c1_b','ka','კორექტირებული ასაკი = რეალური (ქრონოლოგიური) ასაკი − ნაადრევად დაბადების პერიოდი. მაგალითად, თუ ბავშვი 2 თვით ადრე დაიბადა და ახლა 5 თვისაა, მისი კორექტირებული ასაკი 3 თვეა. პრაქტიკაში ეს მშობიარობის სავარაუდო თარიღიდან (EDD) დღემდე გასულ პერიოდს უდრის.','app'),
('preemie_c1_t','ka','როგორ გამოითვლება?','app'),
('preemie_c2_b','ka','განვითარების ეტაპები (გადაბრუნება, ჯდომა, სიარული), ზრდის მრუდები (წონის/სიმაღლის პერცენტილები), თამაშებისა და აქტივობების შერჩევა — ყველაფერი კორექტირებული ასაკით უნდა შეფასდეს. Anacan ამას ავტომატურად ითვალისწინებს: ზრდის გრაფიკი, განვითარების ყოველდღიური კონტენტი და თამაშების რეკომენდაციები უკვე კორექტირებული ასაკით მუშაობს.','app'),
('preemie_c2_t','ka','სად გამოიყენება?','app'),
('preemie_c3_b','ka','ვაქცინაცია ტარდება არა კორექტირებული ასაკის, არამედ დაბადების რეალური თარიღის მიხედვით (საერთაშორისო სტანდარტი — ჯანმო/AAP). ნუ გადადებთ ვაქცინაციას: ვადაზე ადრე დაბადებული ბავშვები ინფექციების მიმართ უფრო მგრძნობიარენი არიან და დაცვა უფრო ადრე სჭირდებათ.','app'),
('preemie_c3_t','ka','სად არ გამოიყენება?','app'),
('preemie_c4_b','ka','ჩვეულებრივ, კორექტირებული ასაკის 24 თვემდე (2 წლამდე). ამ ასაკის შემდეგ ბავშვების უმეტესობა თანატოლებს ეწევა და კორექტირება აღარ სჭირდება. ზოგ შემთხვევაში (ძალიან ადრე დაბადებულებისთვის) ექიმმა შესაძლოა 3 წლამდე გაგრძელება გირჩიოთ.','app'),
('preemie_c4_t','ka','რამდენ ხანს?','app'),
('preemie_corrected_label','ka','კორექტირებული ასაკი','app'),
('preemie_corrected_short','ka','კორექტირება','app'),
('preemie_d1_b','ka','15-20 წამზე ხანგრძლივი სუნთქვის შეჩერება (აპნოე), კვნესით სუნთქვა, ნესტოების გაფართოება, ნეკნთაშუა ჩაზნექა, ტუჩების/სახის გალურჯება — დაუყოვნებლივ დარეკეთ 112-ზე.','app'),
('preemie_d1_t','ka','სუნთქვის პრობლემები','app'),
('preemie_d2_b','ka','თუ იღლიის ტემპერატურა 36.4°C-ზე დაბალია ან 38°C-ზე მაღალია — ვადაზე ადრე დაბადებულ ბავშვთან ორივე შემთხვევა სერიოზულად უნდა შეფასდეს და დაუყოვნებლივ ეცნობოს ექიმს. ნუ ეცდებით სიცხის სახლში "დაწევას" და ნუ დაელოდებით.','app'),
('preemie_d2_t','ka','ტემპერატურა','app'),
('preemie_d3_b','ka','ზედიზედ 2-3 კვებაზე უარის თქმა, უჩვეულო მოდუნება/ვერ გაღვიძება, მუდმივი ღებინება (განსაკუთრებით მწვანე ფერის) — გადაუდებელ შეფასებას საჭიროებს.','app'),
('preemie_d3_t','ka','კვება და აქტივობა','app'),
('preemie_d4_b','ka','24 საათში 4-ზე ნაკლები სველი საფენი, ჩაზნექილი ყიფლიბანდი, ტირილისას ცრემლების არქონა — გაუწყლოების ნიშნებია. სრული სია Anacan-ის "საფრთხის ნიშნების" ხელსაწყოშია.','app'),
('preemie_d4_t','ka','გაუწყლოების ნიშნები','app'),
('preemie_dash_entry_sub','ka','NICU, კენგურუს მეთოდი, კვება და კორექტირებული ასაკი','app'),
('preemie_dash_entry_title','ka','დღენაკლული ბავშვის გზამკვლევი','app'),
('preemie_f1_b','ka','მაშინაც კი, თუ ბავშვი ჯერ ვერ წოვს, მშობიარობიდან პირველი 6 საათის განმავლობაში დაიწყეთ რძის გამოწველა და განაგრძეთ დღეში 8-10-ჯერ (ღამის ჩათვლით) — ეს რძის გამომუშავებას შეინარჩუნებს. ხსენის პირველი წვეთიც კი ძვირფასია; მიაწოდეთ NICU-ს.','app'),
('preemie_f1_t','ka','პირველი დღეები: გამოწველის რეჟიმი','app'),
('preemie_f2_b','ka','წოვა-ყლაპვა-სუნთქვის კოორდინაცია, ჩვეულებრივ, 32-34 კვირისთვის ყალიბდება. გადასვლა ეტაპობრივია: ჯერ ზონდით კვებისას ძუძუსთან „გაცნობა“ (არასაკვები წოვა), შემდეგ ხანმოკლე ძუძუთი კვება და ბოლოს სრული გადასვლა. მოთმინება გამოიჩინეთ — ამ უნარს ვარჯიში სჭირდება.','app'),
('preemie_f2_t','ka','ზონდიდან ძუძუზე გადასვლა ეტაპობრივია','app'),
('preemie_f3_b','ka','ზოგ დღენაკლულ ბავშვს უნიშნავენ დედის რძის გამამდიდრებელს, რომელიც დამატებით კალორიებს, ცილებსა და მინერალებს შეიცავს — ეს არ ნიშნავს, რომ დედის რძე „არასაკმარისია“, უბრალოდ დღენაკლული ბავშვის მოთხოვნილება უფრო მაღალია. გამოიყენება მხოლოდ ექიმის დანიშნულებით.','app'),
('preemie_f3_t','ka','რა არის გამამდიდრებელი (fortifier)?','app'),
('preemie_f4_b','ka','წონის მატება დღენაკლული ბავშვის ერთ-ერთი უმნიშვნელოვანესი მაჩვენებელია. მონაცემები შეიტანეთ Anacan-ის ზრდის ტრეკერში — გრაფიკი ავტომატურად აიგება კორეგირებული ასაკის მიხედვით, რათა თქვენი ბავშვი თანატოლებს სწორად შეადაროთ.','app'),
('preemie_f4_t','ka','წონის მონიტორინგი','app'),
('preemie_hub_disclaimer','ka','ეს ინფორმაცია საგანმანათლებლო ხასიათისაა და ექიმის გამოკვლევას/კონსულტაციას არ ცვლის. თქვენს ბავშვთან დაკავშირებული ყველა გადაწყვეტილება პედიატრთან ერთად მიიღეთ.','app'),
('preemie_hub_eyebrow','ka','დღენაკლული ბავშვები','app'),
('preemie_hub_generic_intro','ka','მსოფლიოში ყოველი 10 ბავშვიდან ~1 ნაადრევად (37 კვირამდე) იბადება. ეს გზამკვლევი დაგეხმარებათ NICU-ში გატარებული დღეებიდან სახლში პირველ თვეებამდე.','app'),
('preemie_hub_status_chrono','ka','რეალური ასაკი','app'),
('preemie_hub_status_corrected','ka','კორეგირებული ასაკი','app'),
('preemie_hub_status_note','ka','ზრდის გრაფიკი, განვითარების მასალები და თამაშის რეკომენდაციები ავტომატურად კორეგირებული ასაკის მიხედვით მუშაობს.','app'),
('preemie_hub_title','ka','დღენაკლული ბავშვის გზამკვლევი','app'),
('preemie_i1_b','ka','ბავშვთან შეხებამდე ყველამ ხელები საპნით უნდა დაიბანოს ან დაიმუშაოს სადეზინფექციო საშუალებით — გამონაკლისის გარეშე. ეს დაცვის ყველაზე მარტივი და ეფექტური გზაა.','app'),
('preemie_i1_t','ka','ოქროს წესი: ხელების დაბანა','app'),
('preemie_i2_b','ka','გაციების, ხველის ან სიცხის მქონე არავინ უნდა მიუახლოვდეს ბავშვს. არავის მისცეთ ბავშვის სახესა და ხელებზე კოცნის უფლება. პირველ თვეებში სტუმრების რაოდენობა მინიმუმამდე შეამცირეთ.','app'),
('preemie_i2_t','ka','სტუმრების წესები','app'),
('preemie_i3_b','ka','სიგარეტის კვამლი (ტანსაცმელზე დარჩენილი ნაწილაკების ჩათვლით) დღენაკლულ ბავშვში მკვეთრად ზრდის სუნთქვის პრობლემებისა და ჩვილის უეცარი სიკვდილის სინდრომის (SIDS) რისკს. სახლში და ბავშვთან ახლოს მოწევა სრულად აკრძალეთ.','app'),
('preemie_i3_t','ka','სიგარეტის კვამლი — მკაცრად აკრძალულია','app'),
('preemie_i4_b','ka','RSV (რესპირატორულ-სინციტიური ვირუსი) დღენაკლული ბავშვებისთვის ყველაზე საშიში სეზონური ვირუსია. შემოდგომა-ზამთრის თვეებში მოერიდეთ ხალხმრავალ დახურულ ადგილებს (სავაჭრო ცენტრი, ქორწილი). პედიატრთან განიხილეთ, ეკუთვნის თუ არა თქვენს ბავშვს RSV-სგან დამცავი იმუნიზაცია.','app'),
('preemie_i4_t','ka','სიფრთხილე RSV-ს სეზონზე (შემოდგომა-ზამთარი)','app'),
('preemie_i5_b','ka','დღენაკლული ბავშვები ვაქცინებს რეალური (ქრონოლოგიური) ასაკის მიხედვით, ჩვეულებრივი კალენდრით იღებენ — კორეგირებულ ასაკს არ ელოდებიან. ოჯახის წევრების გრიპისა და ყივანახველის საწინააღმდეგო აცრებიც ბავშვს ირიბად იცავს („კოკონის სტრატეგია“).','app'),
('preemie_i5_t','ka','ნუ გადადებთ აცრებს','app'),
('preemie_k1_b','ka','ასტაბილურებს ბავშვის ტემპერატურას, გულისცემასა და სუნთქვას, აჩქარებს წონის მატებას, აღრმავებს ძილს, ზრდის დედის რძის გამომუშავებას და აძლიერებს მშობლისა და ბავშვის კავშირს. ჯანმო (WHO) კენგურუს მეთოდს ყველა დღენაკლული ბავშვისთვის უწევს რეკომენდაციას.','app'),
('preemie_k1_t','ka','სარგებელი (მეცნიერულად დადასტურებული)','app'),
('preemie_k2_b','ka','მხოლოდ საფენიანი ბავშვი ვერტიკალურად მიიკარით მკერდზე, თავი გვერდზე მიუბრუნეთ (სასუნთქი გზა ღია უნდა იყოს) და ზემოდან რბილი გადასაფარებელი დააფარეთ. კომფორტულად მოკალათდით და დაისვენეთ. თუ NICU-ში ხართ, დრო და წესები სამედიცინო პერსონალთან შეათანხმეთ.','app'),
('preemie_k2_t','ka','როგორ კეთდება?','app')
ON CONFLICT (key, lang) DO UPDATE SET value = EXCLUDED.value, updated_at = now();

INSERT INTO public.translations (key, lang, value, namespace) VALUES
('preemie_k3_b','ka','რაც შეიძლება ხშირად — სასურველია, თითოეული სეანსი სულ მცირე 60 წუთს გაგრძელდეს (ხანმოკლე სეანსები ბავშვს შეიძლება არ ღლიდეს, თუმცა გადაყვანის პროცესი სტრესს იწვევს). ყოველდღიურ ჩვევად აქციეთ.','app'),
('preemie_k3_t','ka','რამდენ ხანს?','app'),
('preemie_k4_b','ka','კენგურუს მეთოდი მხოლოდ დედისთვის არ არის — მამასთან კანი-კანზე კონტაქტიც თანაბრად სასარგებლოა და მას ბავშვთან ადრეული კავშირის დამყარებაში ეხმარება. ჩაენაცვლეთ ერთმანეთს.','app'),
('preemie_k4_t','ka','მამასაც შეუძლია','app'),
('preemie_n1_b','ka','მონიტორები აკონტროლებს გულისცემას, სუნთქვასა და ჟანგბადს; კვების ზონდი ბავშვს რძეს აწვდის, სანამ წოვას ისწავლის; CPAP სუნთქვას ეხმარება; ინკუბატორი სითბოს ინარჩუნებს. განგაშის ხმები ხშირად მცირე ცვლილებებს უკავშირდება — ყველა სიგნალი საფრთხეს არ ნიშნავს.','app'),
('preemie_n1_t','ka','ნუ შეგაშინებთ აპარატურა','app'),
('preemie_n2_b','ka','თქვენი ხმა, შეხება და დედის რძე — ისაა, რასაც ვერანაირი აპარატურა ვერ ჩაანაცვლებს. ესაუბრეთ თქვენს ბავშვს, უმღერეთ და შეძლებისდაგვარად დაამყარეთ კანი-კანზე კონტაქტი. სთხოვეთ სამედიცინო პერსონალს, ჩაგრთონ ბავშვის მოვლაში (საფენის გამოცვლა, ტემპერატურის გაზომვა).','app'),
('preemie_n2_t','ka','თქვენი, როგორც მშობლის, როლი დიდია','app'),
('preemie_n3_b','ka','შეგიძლიათ ყოველდღე იკითხოთ: რამდენს იწონის დღეს? როგორ მიმდინარეობს კვება? როგორია დღევანდელი გეგმა? რა ეტაპები დარჩა სახლში გაწერამდე? კითხვები ტელეფონში ჩაინიშნეთ — შეხვედრისას რომ არ დაგავიწყდეთ.','app'),
('preemie_n3_t','ka','ნუ მოგერიდებათ კითხვების დასმა','app'),
('preemie_n4_b','ka','ჩვეულებრივ, პატარა მზადაა სახლში წასასვლელად, როცა თავად ინარჩუნებს სხეულის ტემპერატურას, ზონდის გარეშე (ძუძუთი ან ბოთლით) იკვებება, წონას სტაბილურად იმატებს და სუნთქვის პაუზები (აპნოე) აღარ აქვს. ეს, როგორც წესი, მშობიარობის სავარაუდო თარიღთან (EDD-სთან) ახლოს ხდება.','app'),
('preemie_n4_t','ka','სახლში გაწერის კრიტერიუმები','app'),
('preemie_n5_b','ka','NICU-ში გატარებული პერიოდი მარათონია და არა სპრინტი. ჭამეთ, დაიძინეთ და ერთმანეთს ჩაენაცვლეთ. ტირილი ნორმალურია. გამოიყენეთ Anacan-ის ფსიქიკური ჯანმრთელობის ხელსაწყო და Community-ში დაუკავშირდით დღენაკლული ბავშვების სხვა მშობლებს — ამ გზას მარტო არ გადიხართ.','app'),
('preemie_n5_t','ka','საკუთარ თავზეც იზრუნეთ','app'),
('preemie_sec_corrected','ka','რა არის კორექტირებული ასაკი?','app'),
('preemie_sec_corrected_intro','ka','დღენაკლული ბავშვის განვითარება ფასდება მშობიარობის სავარაუდო თარიღიდან (EDD) გამოთვლილი ასაკით.','app'),
('preemie_sec_danger','ka','როდის მივმართოთ ექიმს დაუყოვნებლივ?','app'),
('preemie_sec_danger_intro','ka','დღენაკლული ბავშვის მდგომარეობა შეიძლება სწრაფად შეიცვალოს — ამ ნიშნების დროს ნუ დაელოდებით, დაუყოვნებლივ მიმართეთ სამედიცინო დახმარებას.','app'),
('preemie_sec_feeding','ka','კვება და ძუძუთი კვება','app'),
('preemie_sec_feeding_intro','ka','დღენაკლული ბავშვისთვის დედის რძე მხოლოდ საკვები კი არა, წამალიცაა — იცავს ინფექციებისგან და ნაწლავების მომწიფებას უწყობს ხელს.','app'),
('preemie_sec_infection','ka','ინფექციებისგან დაცვა (RSV-ის ჩათვლით)','app'),
