('rf_intro','ka','თუ ამ ნიშნებიდან რომელიმე გაქვთ, ნუ დაელოდებით. ეჭვის შემთხვევაში ყოველთვის მიმართეთ ექიმს — „ტყუილად შევაწუხე“ არ არსებობს.','app'),
('rf_leg_desc','ka','ცალმხრივი ფეხის ტკივილი, სიმხურვალე, სიწითლე — შესაძლოა თრომბის (DVT) ნიშანი იყოს.','app'),
('rf_leg_title','ka','ერთი ფეხის ტკივილი და შეშუპება','app'),
('rf_mental_desc','ka','თუ საკუთარი თავისთვის/ბავშვისთვის ზიანის მიყენებაზე ფიქრობთ — ეს თქვენი ბრალი არ არის, დახმარება ხელმისაწვდომია. დაუყოვნებლივ უთხარით ახლობელს და მიმართეთ სპეციალისტს.','app'),
('rf_mental_title','ka','ძლიერი სევდა ან ზიანის მიყენების აზრები','app'),
('rf_movement_desc','ka','28-ე კვირის შემდეგ ბავშვი ჩვეულ რიტმთან შედარებით შესამჩნევად ნაკლებად მოძრაობს (2 საათში <10 მოძრაობა).','app'),
('rf_movement_title','ka','ბავშვის მოძრაობა შემცირდა','app'),
