('rf_partner_done','ka','ეცნობა ✓','app'),
('rf_partner_msg_suffix','ka','დაუყოვნებლივ დამიკავშირდით!','app'),
('rf_partner_notified','ka','თქვენს პარტნიორს ეცნობა 💙','app'),
('rf_pp_bleeding_desc','ka','1 საათში 1-ზე მეტი საფენი იჟღინთება ან დიდი კოლტები გამოიყოფა.','app'),
