('rf_soon_guidance','ka','📞 დღესვე დაუკავშირდით თქვენს ექიმს და დააკვირდით მდგომარეობას.','app'),
('rf_soon_section','ka','ექიმთან დაკავშირება დღესვე','app'),
('rf_swelling_desc','ka','უეცარი შეშუპება (განსაკუთრებით სახეზე/ხელებზე) — პრეეკლამფსიის რისკი.','app'),
('rf_swelling_title','ka','სახისა და ხელების უეცარი შეშუპება','app'),
('rf_title','ka','საფრთხის ნიშნები','app'),
('rf_ttts_desc','ka','მუცლის მოულოდნელად სწრაფი/არათანაბარი ზრდა, ქოშინის უეცარი გაძლიერება, ფეხების უეცარი შეშუპება ან ერთი ბავშვის მოძრაობის შემცირება მეორესთან შედარებით — საერთო პლაცენტის მქონე (მონოქორიონულ) ტყუპებში/სამეულში შესაძლოა TTTS-ის (ტყუპიდან ტყუპზე ტრანსფუზიის სინდრომის) ნიშანი იყოს. დროულად აღმოჩენისა და მკურნალობისას ეს მდგომარეობა კარგად მართვადია, თუმცა აუცილებელია ექიმთან დროულად მიმართვა.','app'),
('rf_ttts_title','ka','ტყუპების არათანაბარი ზრდის ნიშნები (TTTS)','app'),
('rf_urgent_chip','ka','გადაუდებელი','app'),
('rf_urgent_guidance','ka','⚠️ ნუ დაელოდებით: დაუყოვნებლივ დაურეკეთ თქვენს ექიმს ან მიმართეთ გადაუდებელ დახმარებას (112).','app'),
('rf_urgent_guidance_n','ka','⚠️ ნუ დაელოდებით: დაუყოვნებლივ დაურეკეთ თქვენს ექიმს ან მიმართეთ გადაუდებელ დახმარებას ({n}).','app'),
